// Apply fn to all pages in m matching the given predicate.
// fn may return true to stop the walk.
func (m *pageMap) forEachPage(include predicate.P[*pageState], fn func(p *pageState) (bool, error)) error {
	if include == nil {
		include = func(p *pageState) bool {
			return true
		}
	}
	w := &doctree.NodeShiftTreeWalker[contentNodeI]{
		Tree:     m.treePages,
		LockType: doctree.LockTypeRead,
		Handle: func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
			if p, ok := n.(*pageState); ok && include(p) {
				if terminate, err := fn(p); terminate || err != nil {
					return terminate, err
				}
			}
			return false, nil
		},
	}

	return w.Walk(context.Background())
}

func (m *pageMap) forEeachPageIncludingBundledPages(include predicate.P[*pageState], fn func(p *pageState) (bool, error)) error {
	if include == nil {
		include = func(p *pageState) bool {
			return true
		}
	}

	if err := m.forEachPage(include, fn); err != nil {
		return err
	}

	w := &doctree.NodeShiftTreeWalker[contentNodeI]{
		Tree:     m.treeResources,
		LockType: doctree.LockTypeRead,
		Handle: func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
			if rs, ok := n.(*resourceSource); ok {
				if p, ok := rs.r.(*pageState); ok && include(p) {
					if terminate, err := fn(p); terminate || err != nil {
						return terminate, err
					}
				}
			}
			return false, nil
		},
	}

	return w.Walk(context.Background())
}

func (m *pageMap) getOrCreatePagesFromCache(
	key string, create func(string) (page.Pages, error),
) (page.Pages, error) {
	return m.cachePages.GetOrCreate(key, create)
}

func (s *Site) getPagesInSection(q pageMapQueryPagesInSection) page.Pages {
	m := s.pageMap
	cacheKey := "gagesInSection/" + q.Path + "/" + q.KeyPart + "/" + strconv.FormatBool(q.Recursive) + "/" + strconv.FormatBool(q.IncludeSelf) + "/" + m.cfg.lang

	pages, err := m.cachePages.GetOrCreate(cacheKey, func(string) (page.Pages, error) {
		prefix := paths.AddTrailingSlash(q.Path)

		var pas page.Pages

		requestedInclude := q.Include
		if requestedInclude == nil {
			requestedInclude = pagePredicates.ShouldListLocal
		}
		include := func(p *pageState) bool {
			pm := p.m
			pagePath := pm.Path()
			pageKind := pm.Kind()
			if pm.bundled {
				return false
			}
			if pageKind == "" && pagePath == "" {
				return false
			}
			if q.Path != "" && pagePath != q.Path && !strings.HasPrefix(pagePath, prefix) {
				return false
			}
			return requestedInclude(p)
		}

		var w *doctree.NodeShiftTreeWalker[contentNodeI]
		w = &doctree.NodeShiftTreeWalker[contentNodeI]{
			Tree:   m.treePages,
			Prefix: prefix,
			Handle: func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
				if q.Recursive {
					if p, ok := n.(*pageState); ok && include(p) {
						pas = append(pas, p)
					}
					return false, nil
				}

				if p, ok := n.(*pageState); ok && include(p) {
					pas = append(pas, p)
				}
				if n.isContentNodeBranch() {
					w.SkipPrefix(key + "/")
				}

				return false, nil
			},
		}

		err := w.Walk(context.Background())

		if err == nil {
			if q.IncludeSelf {
				if n := m.treePages.Get(q.Path); n != nil {
					if p, ok := n.(*pageState); ok && include(p) {
						pas = append(pas, p)
					}
				}
			}
			page.SortByDefault(pas)
		}

		return pas, err

